const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const coinLabel=n=>`${n} ${n===1?'coin':'coins'}`;
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
const runtime=n=>`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;
const key=(id,part)=>`${id}:${part}`;
const freeDate=(date=FREE_AT)=>new Date(date).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
const early=(id,part)=>episodeAccess(episodeBy(id,part),state)==='locked';
let state={balance:0,saved:['moonflower'],unlocked:[],progress:{},history:[],receipts:[],completed:[],demoRelease:'before',drafts:structuredClone(DEMO_DRAFTS),reminders:[]};
try{const stored=JSON.parse(localStorage.getItem('frame-demo-v3')||'null');if(stored&&Array.isArray(stored.saved)&&Array.isArray(stored.drafts))state={...state,...stored};}catch{}
if(!state.catalogVersion){const retiredSamples={'sample-last-light':'The Last Light','sample-night-shift':'Night Shift'};state.drafts=state.drafts.filter(d=>!(d.sample&&retiredSamples[d.id]===d.title&&!d.coverKey&&d.episodes.every(e=>!e.videoKey&&!e.mediaKey)));for(const sample of DEMO_DRAFTS)if(!state.drafts.some(d=>d.id===sample.id))state.drafts.push(structuredClone(sample));state.catalogVersion=1;}
state.drafts=state.drafts.map(d=>({...d,shelf:['Originals','Explore'].includes(d.shelf)?d.shelf:'Explore'}));
for(const field of ['completed','history','unlocked','receipts','reminders','saved'])if(!Array.isArray(state[field]))state[field]=[];state.progress=Object.fromEntries(Object.entries(state.progress||{}).filter(([,v])=>Number.isFinite(v)&&v>=0));if(!Number.isFinite(state.balance)||state.balance<0)state.balance=0;state.demoRelease ||= 'before';let playbackHeld=false;let origins={};try{origins=JSON.parse(sessionStorage.getItem('dd-origins')||'{}');}catch{}
let modalVersion=0,pageVersion=0,pageUrls=[];
let category=location.hash==='#explore'?'Explore':'Originals',query='',libraryTab='Continue',feature=0,modalReturn=null,modalUrls=[],toastTimer,route='',scrollPositions={},lastRoute='home';
function persist(){try{localStorage.setItem('frame-demo-v3',JSON.stringify(state));return true;}catch{toast('Your browser could not save this change.');return false;}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',explore:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M16 8l-3 5-5 3 3-5Z',library:'M4 4h5v17H4zM13 4h5l3 17h-5Z',profile:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-2a8 8 0 0 1 16 0v2',search:'m16 16 5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',play:'m8 5 11 7-11 7Z',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',coin:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v10M9 9h5a2 2 0 0 1 0 4h-4a2 2 0 0 0 0 4h5',studio:'M4 4h16v16H4zM12 8v8M8 12h8',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4ZM10 21h4',lock:'M6 10h12v11H6zM8 10V7a4 4 0 0 1 8 0v3',chevron:'m9 5 7 7-7 7',card:'M3 5h18v14H3zM3 10h18M6 15h4',edit:'m5 16 11-11 3 3-11 11-4 1ZM14 7l3 3',heart:'M12 21 3 12a5 5 0 0 1 9-6 5 5 0 0 1 9 6Z'};
function icon(name,size=20){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.arrow}"/></svg>`;}
function nav(bottom=false){return ['home','explore','library','profile'].map(id=>`<a class="navItem ${route===id?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''}>${icon(id)}<span>${id==='home'?(bottom?'Home':'Discover'):id[0].toUpperCase()+id.slice(1)}</span></a>`).join('');}
function heading(title,subtitle=''){return `<div class="pageHeading"><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>`;}
function currentRoute(){return location.hash.slice(1)||'home';}
function go(next){if(currentRoute()===next){render();return;}location.hash=next;}
function render(){const active=document.activeElement;const focusIdentity=Object.fromEntries(['action','id','category','tab','episode','direction'].map(k=>[k,active?.dataset?.[k]]));pageVersion++;pageUrls.forEach(URL.revokeObjectURL);pageUrls=[];const v=$('#main video');if(v){v.pause();persist();}route=currentRoute();document.body.classList.toggle('watching',route.startsWith('watch/'));document.body.classList.toggle('detailScreen',route.startsWith('series/'));const page=route.split('/');document.body.dataset.page=page[0];let content;
 if(page[0]==='series')content=detail(page[1]);else if(page[0]==='watch')content=player(page[1],page[2]);else content=({home,explore,library,profile,wallet,studio}[route]||home)();
 $('#app').innerHTML=`<header class="siteHeader"><a class="logo" href="#home" aria-label="Death & Desire home"><span class="brandTop">DEATH <b>&</b></span><span class="brandBottom">DESIRE</span></a><nav aria-label="Main navigation">${nav()}</nav><div class="headerTools"><a class="studioLink" href="#studio">Creator studio ${icon('arrow',16)}</a><button class="themeTrigger" data-action="appearance" aria-label="Choose appearance">Theme</button><a class="iconButton" href="#explore" aria-label="Search stories">${icon('search')}</a><a class="avatar" href="#profile" aria-label="Your profile">P</a></div></header><main id="main" tabindex="-1">${content}</main><footer class="siteFooter"><a class="logo" href="#home"><span class="brandTop">DEATH <b>&</b></span><span class="brandBottom">DESIRE</span></a><p>A world of stories. A little closer.</p><a href="#profile">About this preview</a></footer><nav class="bottomNav" aria-label="App navigation">${nav(true)}</nav>`;
 const search=$('#search');if(search){document.querySelector('.chips').hidden=!!query.trim();search.oninput=()=>{query=search.value;document.querySelector('.chips').hidden=!!query.trim();$('#searchResults').innerHTML=searchResults();};}if(page[0]==='watch')bindPlayer(page[1],page[2]);if(page[0]==='home')observeFeature();if(route==='studio')hydrateCovers(pageVersion);hydratePageMedia(pageVersion);if(focusIdentity.action){const replacement=[...document.querySelectorAll('[data-action]')].find(e=>Object.entries(focusIdentity).every(([k,v])=>e.dataset[k]===v));replacement?.focus({preventScroll:true});}const clock=$('#demoRelease');if(clock)clock.onchange=()=>{const next=structuredClone(state);next.demoRelease=clock.value;if(!commitState(next))toast('The demo timing could not be saved.');};
}
window.addEventListener('hashchange',()=>{scrollPositions[lastRoute]=scrollY;if($('#modal').open)closeModal();render();$('#main').focus({preventScroll:true});window.scrollTo(0,scrollPositions[route]||0);lastRoute=route;});
function poster(s,eager=false){return `<div class="poster ${s.interactive?'interactivePoster':''}"><img src="${esc(s.cover)}" ${s.coverKey?`data-media-key="${s.coverKey}"`:""} alt="" loading="${eager?'eager':'lazy'}" ${eager?'fetchpriority="high"':''}>${s.interactive?'<div class="posterText"><span>YOUR STORY STARTS HERE</span>Solera<br><i>First Arrival</i></div>':''}${s.comingSoon?'<span class="posterLabel">Coming soon</span>':''}</div>`;}
function card(s){return `<a href="#series/${s.id}" class="storyCard">${poster(s)}<h3>${s.title}</h3><p>${s.genre}</p></a>`;}
function rail(title,ids,cat='',subtitle=''){return `<section class="shelf"><div class="sectionTitle"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${cat?`<button class="viewAll" data-action="category" data-category="${cat}">View all ${icon('chevron',16)}</button>`:''}</div><div class="rail">${ids.map(id=>card(getSeries(id))).join('')}</div></section>`;}
function chips(){return `<div class="chips" aria-label="Story categories">${CATEGORIES.map(c=>`<button class="chip ${category===c?'selected':''}" aria-pressed="${category===c}" data-action="filter" data-category="${c}">${c}</button>`).join('')}</div>`;}
function hero(){return `<div class="featureTrack" aria-label="Featured stories">${SERIES.slice(0,3).map((s,i)=>`<article class="feature ${s.theme}"><img class="featureImage" src="assets/${s.id}-hero.jpg" alt="" ${i===0?'fetchpriority="high"':'loading="lazy"'}><div class="featureShade"></div><div class="featureCopy"><span class="overline">D&D ORIGINAL</span><h1>${s.title}</h1><p>${s.hook}</p><div class="featureActions"><a class="primary" href="${primaryFor(s).href}">${icon('play',18)} ${esc(primaryFor(s).label)}</a><a class="featureMore" href="#series/${s.id}" aria-label="Explore ${s.title}">${icon('plus',21)}</a></div></div></article>`).join('')}</div><div class="featureDots">${SERIES.slice(0,3).map((s,i)=>`<button data-action="feature" data-index="${i}" class="${i===feature?'active':''}" aria-label="Feature ${s.title}" aria-pressed="${i===feature}"></button>`).join('')}</div>`;}
function home(){return `<div class="homeTop"><div class="desktopIntro"><span class="overline">DEATH & DESIRE ORIGINALS</span><h1>Stories you’ll feel.</h1></div>${chips()}</div><div id="homeResults">${homeContent()}</div>`;}
function homeContent(){if(category==='Explore')return `<section class="filteredHome">${heading('Explore')}<div class="browseGrid">${SERIES.filter(s=>!s.shelves.includes('Originals')).map(card).join('')}</div></section>`;return `<section class="featureWrap">${hero()}</section>${state.history.some(k=>SERIES.some(s=>k.startsWith(s.id+':')))?`<section class="continueSection">${continueCard()}</section>`:''}${rail('Originals',['winter','second-chance','moonflower'],'Originals')}`;}

function observeFeature(){const track=$('.featureTrack');if(!track)return;track.scrollLeft=feature*track.clientWidth;let frame;track.onscroll=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{feature=Math.round(track.scrollLeft/track.clientWidth);document.querySelectorAll('.featureDots button').forEach((b,i)=>{b.classList.toggle('active',i===feature);b.setAttribute('aria-pressed',i===feature);});});};}
function explore(){return `${heading('Find your next story.')}<label class="searchField">${icon('search')}<input id="search" type="search" placeholder="Search stories, genres, creators" value="${esc(query)}" aria-label="Search stories"></label>${chips()}<div id="searchResults">${searchResults()}</div>`;}
function searchResults(){const filtered=SERIES.filter(s=>(query.trim()|| (category==='Explore'?!s.shelves.includes('Originals'):s.shelves.includes('Originals')))&&`${s.title} ${s.genre} ${s.creator}`.toLowerCase().includes(query.trim().toLowerCase()));return filtered.length?`${query.trim()?'<p class="searchScope">Results across Originals and Explore</p>':''}<div class="browseGrid">${filtered.map(card).join('')}</div>`:`<div class="empty"><h2>No stories found</h2><p>Try a genre like romance, or a creator like Death & Desire.</p><button class="secondary" data-action="clear-search">Clear search</button></div>`;}

function appearanceChoices(){const selected=window.ddAppearance.get();return '<div class="appearanceChoices" role="group" aria-label="Appearance">'+['light','dark','system'].map(value=>'<button data-action="set-appearance" data-appearance="'+value+'" aria-pressed="'+(value===selected)+'">'+value[0].toUpperCase()+value.slice(1)+'</button>').join('')+'</div>';}
function appearancePanel(){return '<section class="appearancePanel"><h2>Appearance</h2><p>Choose your reading light.</p>'+appearanceChoices()+'</section>';}
function showAppearance(){openModal('<section class="appearanceSheet"><h2>Make yourself at home.</h2><p>Choose a look, or follow your device.</p>'+appearanceChoices()+'<p class="fineprint">The video player keeps a dark background in every theme.</p></section>','appearanceDialog');}

function profile(){return `${heading('Your space')}<div class="profileGrid"><section><div class="profileIdentity"><span class="largeAvatar">P</span><div><h2>Story explorer</h2><p>A sample profile for this preview</p></div></div><a class="accountBalance" href="#wallet"><span>${icon('coin',26)}<span>Your coins<strong>${state.balance} ${state.balance===1?'coin':'coins'}</strong></span></span>${icon('chevron')}</a><div class="accountLinks"><a href="#library">${icon('library')}Your library${icon('chevron')}</a><a href="#studio">${icon('studio')}Creator studio${icon('chevron')}</a><button data-action="how-it-works">${icon('heart')}How early access works${icon('chevron')}</button></div>${appearancePanel()}</section><aside class="aboutPreview"><span class="overline">WELCOME TO DEATH & DESIRE</span><h2>Stories on your terms.</h2><p>Watch released episodes for free. If you want the next one sooner, support its creator with early access.</p><div class="previewNote"><strong>You're exploring a product demo.</strong><p>Story titles and cover art come from the Death & Desire catalogue. Profile and studio activity are demo examples. Purchases are simulated. Your saved stories and drafts stay in this browser.</p><details class="previewTools"><summary>Preview controls</summary><label>Release timing<select id="demoRelease"><option value="before" ${state.demoRelease==='before'?'selected':''}>Before free release</option><option value="after" ${state.demoRelease==='after'?'selected':''}>After free release</option></select></label><button class="textButton" data-action="reset-purchases">Reset demo purchases</button><button class="textButton" data-action="reset-viewing">Reset viewing progress</button></details></div></aside></div>`;}
function notFound(){return `<div class="empty"><h1>That story isn't here.</h1><a class="primary" href="#explore">Find another story</a></div>`;}
function wallet(){return `${heading('Your coins','A little early access. A little support for the storyteller.')}<div class="walletLayout"><section class="walletPanel"><span class="overline">AVAILABLE TO USE</span><h2>${icon('coin',36)} ${state.balance}<span>${state.balance===1?'coin':'coins'}</span></h2><p>1 coin = US$1.00</p><button class="primary" data-action="topup">Add coins ${icon('plus',18)}</button></section><section class="walletExplainer"><h2>Pay only when you can't wait.</h2><p>Released episodes are free. Coins let you watch selected episodes ahead of their free release.</p><div class="ruleRow">${icon('check')}Creators earn a share of coins spent on their series.</div><div class="ruleRow">${icon('check')}A separate fee appears before you pay.</div><div class="ruleRow">${icon('check')}No subscription. No automatic unlocks.</div><small>Illustrative pricing: US$1 per coin, 10% platform fee on coin purchases. These are demo assumptions, not live prices. Creator revenue shares and Originals terms are still being defined.</small></section></div><section class="receiptSection"><div class="sectionTitle"><h2>Recent activity</h2><span class="quietLabel">Demo transactions</span></div>${state.receipts.length?state.receipts.slice().reverse().map(r=>`<button class="receiptRow" data-action="receipt" data-id="${r.id}"><span class="receiptIcon">${icon(r.kind==='unlock'?'play':'coin')}</span><span><strong>${esc(r.title)}</strong><small>${esc(r.date)} · ${money(r.cash)} demo payment</small></span><b>${r.kind==='unlock'?'-'+coinLabel(r.spent??r.coins):'+'+coinLabel(r.added??r.coins)} ${icon('chevron',16)}</b></button>`).join(''):`<div class="activityEmpty"><p>Your receipts will appear here.</p><a href="#series/winter">Try an early-access episode ${icon('arrow',16)}</a></div>`}</section>`;}
function clearModalMedia(){modalVersion++;document.querySelectorAll('#modal video').forEach(v=>v.pause());modalUrls.forEach(u=>URL.revokeObjectURL(u));modalUrls=[];}
function openModal(html,cls=''){if(!$('#modal').open)modalReturn=document.activeElement;clearModalMedia();$('#modal').className=cls;$('#modal').innerHTML=`<div class="sheetHandle"></div><button class="close iconButton" data-action="close" aria-label="Close dialog">${icon('close')}</button>${html}`;$('#modal').setAttribute('aria-label',$('#modal h2')?.textContent||'Death & Desire dialog');if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;$('#modal .close')?.focus({preventScroll:true});}
function closeModal(){clearModalMedia();$('#modal').close();}
$('#modal').addEventListener('close',()=>{playbackHeld=false;clearModalMedia();if(modalReturn?.isConnected)modalReturn.focus();});
function topup(amount=5){const fee=Math.round(amount*10)/100;openModal(`<div class="checkoutContent"><span class="overline">YOUR COINS</span><h2>A few stories ahead.</h2><p class="muted">One coin is one dollar. Choose only what you need.</p><div class="coinOptions">${[1,5,10].map(n=>`<button class="${n===amount?'selected':''}" data-action="choose-coins" data-amount="${n}" aria-pressed="${n===amount}">${icon('coin',22)}<strong>${n} ${n===1?'coin':'coins'}</strong><span>${money(n)}</span></button>`).join('')}</div><div class="priceRows"><div><span>Coins added</span><b>${coinLabel(amount)}</b></div><div><span>Platform fee (10%)</span><b>${money(fee)}</b></div><div class="priceTotal"><strong>Total today</strong><strong>${money(amount+fee)}</strong></div></div><div class="paymentMethod">${icon('card')}<div><strong>Demo payment</strong><span>No card details needed. No real charge.</span></div></div><p id="transactionError" class="inlineError" role="alert" hidden></p><button class="primary full" data-action="buy-coins" data-amount="${amount}">Demo pay ${money(amount+fee)}</button><p class="fineprint">No subscription. Illustrative prices in US dollars.</p></div>`,'checkoutSheet');}
function howItWorks(){openModal(`<div class="checkoutContent"><span class="overline">WATCH ON YOUR TERMS</span><h2>Early is optional.</h2><p>Watch released episodes for free. Buy early access only when you want the next chapter sooner.</p><p>The episode price, free-release date, and any platform fee appear before you confirm. If you need coins, add the exact shortfall in the same checkout.</p><a class="primary full" href="#wallet" data-action="close">Explore your coins ${icon('arrow')}</a><p class="fineprint">All transactions in this preview are simulated.</p></div>`);}
async function hydrateCovers(version){for(const d of state.drafts){if(!d.coverKey)continue;try{const file=await readFile(d.coverKey);if(version!==pageVersion)return;if(!file)continue;const node=document.querySelector('[data-cover-id="'+d.id+'"]');if(!node)continue;const url=URL.createObjectURL(file);pageUrls.push(url);const old=node.querySelector('img,.projectPlaceholder');const img=document.createElement('img');img.src=url;img.alt='';old?.replaceWith(img);}catch{}}}
let dbPromise;
function db(){return dbPromise ||= new Promise((resolve,reject)=>{const r=indexedDB.open('frame-studio-media',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function putFile(id,file){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function readFile(id){if(!id)return null;const d=await db();return new Promise((resolve,reject)=>{const r=d.transaction('files').objectStore('files').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function blobUrl(id){const file=await readFile(id);if(!file)return '';const url=URL.createObjectURL(file);modalUrls.push(url);return url;}
function seriesEditor(id){const d=state.drafts.find(x=>x.id===id)||{title:'',genre:'',shelf:'Explore',description:'',tags:''};openModal(`<form class="editorForm" id="seriesForm" data-id="${id||''}"><span class="overline">${id?'EDIT SERIES':'NEW SERIES'}</span><h2>Give your story a home.</h2><label>Series title<input name="title" required maxlength="100" value="${esc(d.title)}" placeholder="The name they'll remember"></label><div class="formRow"><label>Discovery shelf<select name="shelf">${CATEGORIES.map(c=>`<option ${d.shelf===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Genre<input name="genre" required value="${esc(d.genre)}" placeholder="e.g. Sci-fi mystery"></label></div><label>About the story<textarea name="description" required maxlength="700" placeholder="A world worth stepping into">${esc(d.description)}</textarea></label><label>Tags<input name="tags" value="${esc(d.tags)}" placeholder="Mystery, found family, future cities"></label><label class="fileDrop">${icon('plus',24)} Cover artwork<input name="cover" type="file" accept="image/png,image/jpeg,image/webp"><small>Portrait image. Stored on this device.</small></label><p id="seriesError" class="inlineError" role="alert" hidden></p><button class="primary full" type="submit">Save series ${icon('check',18)}</button><p class="fineprint">This saves a local draft. Nothing is published.</p></form>`,'editorSheet');$('#seriesForm').onsubmit=saveSeries;}
function getSeries(id) {
  if (id?.startsWith('draft-')) {
    const d=state.drafts.find(x=>x.id===id.slice(6));
    if(!d)return null;
    return {id,title:d.title,genre:d.genre,description:d.description,creator:'Your studio',shelves:[d.shelf],cover:d.cover||'assets/draft-cover.svg',coverKey:d.coverKey,localPreview:true,draft:d,parts:d.episodes.map(e=>e.id),durations:d.episodes.map(e=>e.duration||0)};
  }
  return SERIES.find(s=>s.id===id);
}
function episodesFor(series) {
  if(!series?.parts)return [];
  if(series.localPreview)return series.draft.episodes.map((e,i)=>({id:key(series.id,e.id),seriesId:series.id,part:e.id,number:String(i+1),label:e.title||`Episode ${i+1}`,duration:e.duration||0,still:series.cover,coverKey:series.coverKey,mediaKey:e.mediaKey,ready:!!e.mediaKey,localPreview:true,price:e.early?e.price:0,freeAt:e.date?e.date+'T00:00:00Z':null,status:e.status}));
  return series.parts.map((part,i)=>({id:key(series.id,part),seriesId:series.id,part,number:part,label:series.episodeTitles?.[part]||`Part ${part}`,duration:series.durations[i],still:`assets/episodes/${series.id}-${part}.jpg`,src:`media/${series.id}-${part}.mp4`,ready:true,price:series.id==='winter'&&part==='5'?PRICE:0,freeAt:series.id==='winter'&&part==='5'?FREE_AT:null}));
}
function episodeBy(id,part){return episodesFor(getSeries(id)).find(e=>e.part===part);}
function accessLabel(e){const a=episodeAccess(e,state);return a==='locked'?`${coinLabel(e.price)} · Free ${freeDate(e.freeAt)}`:a==='unavailable'?'Video not attached':a==='preview'?'Local preview':state.completed.includes(e.id)?'Watched':(state.progress[e.id]||0)>0?'In progress':a==='unlocked'?'Unlocked':'Free';}
function commitState(next){try{state=commitStoredState(localStorage,'frame-demo-v3',next);return true;}catch{return false;}}
function imageTag(src,alt='',attrs=''){return `<img src="${esc(src)}" alt="${esc(alt)}" ${attrs} loading="lazy">`;}
function primaryFor(s){const list=episodesFor(s),r=episodeRecommendation(list,state);if(!r.episode)return {label:'No video attached',href:'#studio',kind:r.kind};const e=r.episode,a=episodeAccess(e,state);let label=a==='locked'?`Watch ${e.label} early · ${coinLabel(e.price)}`:r.kind==='resume'?`Resume ${e.label}`:r.kind==='caught-up'?'Replay from the beginning':r.kind==='start'?`Watch ${e.label}`:`Continue ${e.label}`;return {label,href:`#watch/${s.id}/${e.part}`,kind:r.kind,episode:e};}
function episodeRow(s,e,current=false){const a=episodeAccess(e,state),done=state.completed.includes(e.id),progress=done?100:Math.min(100,(state.progress[e.id]||0)/Math.max(1,e.duration)*100);return `<a class="episodeRow ${current?'current':''} ${a==='unavailable'?'notReady':''}" href="${a==='unavailable'?'#studio':`#watch/${s.id}/${e.part}`}" ${current?'aria-current="true"':''}><span class="episodeStill">${imageTag(e.still,'',e.coverKey?`data-media-key="${e.coverKey}"`:'')}<span class="episodeRuntime">${e.duration?runtime(e.duration):'Preview'}</span></span><span class="episodeWords"><strong>${esc(e.label)}</strong><span>${current?(a==='locked'?accessLabel(e):a==='unavailable'?'Video not attached':'Current episode'):accessLabel(e)}</span>${progress>0&&a!=='locked'?`<span class="episodeProgress"><i style="width:${progress}%"></i></span>`:''}</span><span class="episodeSymbol">${icon(a==='locked'?'lock':done?'check':'play',18)}</span></a>`;}
function rememberOrigin(id){if(route.startsWith('series/')||route.startsWith('watch/'))return;origins[id]={route,scroll:scrollY,query,category,libraryTab};}
function returnOrigin(id){const o=origins[id];if(!o){go('home');return;}query=o.query;category=o.category;libraryTab=o.libraryTab;scrollPositions[o.route]=o.scroll;go(o.route);requestAnimationFrame(()=>scrollTo(0,o.scroll));}
function detail(id){const s=getSeries(id);if(!s)return notFound();const saved=state.saved.includes(id),list=episodesFor(s),main=primaryFor(s);return `<section class="seriesPage"><button class="backLink" data-action="return-origin" data-id="${id}">${icon('back')} ${s.localPreview?'Back to studio':'Back to stories'}</button>${s.localPreview?'<div class="localPreviewBanner">Local creator preview · Nothing is published</div>':''}<div class="seriesIntro"><div class="seriesCover">${poster(s,true)}</div><div class="seriesCopy"><span class="overline">${s.localPreview?'CREATOR PREVIEW':s.comingSoon?'COMING SOON':s.interactive?'INTERACTIVE STORY':'D&D ORIGINAL'}</span><h1>${esc(s.title)}</h1><p class="seriesMeta">${esc(s.genre)} · ${esc(s.creator)}</p><details class="seriesSynopsis"><summary>About this story</summary><p>${esc(s.description)}</p></details><div class="seriesActions">${s.comingSoon?`<button class="primary" data-action="remind" data-id="${id}">${icon(state.reminders.includes(id)?'check':'bell')}${state.reminders.includes(id)?'Reminder saved':'Remind me'}</button>`:s.interactive?'<a class="primary" href="/studio/story-lab-8f3c2a" target="_top">Enter the story ↗</a>':`<a class="primary" href="${main.href}">${icon('play')} ${esc(main.label)}</a>`}${s.localPreview?'<a class="secondary" href="#studio">Back to studio</a>':`<button class="secondary" data-action="save" data-id="${id}" aria-pressed="${saved}">${icon(saved?'check':'plus')}${saved?'Saved':'My list'}</button>`}</div>${main.kind==='caught-up'&&list.length?'<p class="caughtUpNote">You’re caught up with this series.</p>':''}${s.comingSoon?'<p class="conceptNote">No episodes are available yet.</p>':''}</div></div>${list.length?`<section class="episodeSection"><div class="sectionTitle"><h2>Episodes</h2>${main.kind!=='start'&&!s.localPreview?`<button class="viewAll" data-action="start-over" data-id="${id}">Watch from beginning</button>`:''}</div><div class="seriesEpisodeList">${list.map(e=>episodeRow(s,e)).join('')}</div>${!s.localPreview?`<div class="seriesReleaseNote"><span>${icon('bell')} More of this story</span><button class="textButton" data-action="remind" data-id="${id}">${state.reminders.includes(id)?'Reminder saved':'Save a release reminder'}</button></div>`:''}</section>`:s.interactive?'<section class="comingPanel"><h2>Your choices shape the journey.</h2><p>Choose a traveler, explore a training path, and find a companion.</p></section>':!s.comingSoon?'<section class="comingPanel"><h2>Add your first episode.</h2><a class="primary" href="#studio">Open creator studio</a></section>':''}</section>`;}
function continueCard(s){if(!s){const latest=[...state.history].reverse().map(k=>getSeries(k.split(':')[0])).find(x=>x?.parts);s=latest||SERIES.find(x=>x.parts);}const r=episodeRecommendation(episodesFor(s),state),e=r.episode;if(!e)return '';const action=primaryFor(s),pct=state.completed.includes(e.id)?100:Math.min(100,(state.progress[e.id]||0)/Math.max(1,e.duration)*100);return `<a class="continueCard" href="${action.href}">${imageTag(e.still)}<div><span class="overline">${r.kind==='caught-up'?'CAUGHT UP':r.kind==='resume'?'CONTINUE WATCHING':'UP NEXT'}</span><h3>${esc(s.title)}</h3><p class="continueEpisode">${esc(e.label)}${r.kind==='resume'?' · '+runtime(Math.floor(state.progress[e.id]||0)):''}${episodeAccess(e,state)==='locked'?' · Early access':''}</p><div class="progressTrack"><span style="width:${pct}%"></span></div></div><span class="roundPlay">${icon('play')}</span></a>`;}
function nextFor(s,e){const list=episodesFor(s),i=list.findIndex(x=>x.id===e.id);return list[i+1]||null;}
function nextAction(s,e){const next=nextFor(s,e);if(!next)return `<a class="primary" href="#series/${s.id}">Back to series ${icon('arrow')}</a>`;if(!next.ready)return `<a class="primary" href="${s.localPreview?'#studio':'#series/'+s.id}">${s.localPreview?'Attach next video':'Back to episodes'} ${icon('arrow')}</a>`;const locked=episodeAccess(next,state)==='locked';return `<a class="primary" href="#watch/${s.id}/${next.part}">${locked?`Watch ${esc(next.label)} early · ${coinLabel(next.price)}`:`Play ${esc(next.label)}`} ${icon('arrow')}</a>`;}
function endCard(s,e){const next=nextFor(s,e),locked=next&&episodeAccess(next,state)==='locked',allComplete=episodesFor(s).filter(x=>x.ready).every(x=>state.completed.includes(x.id));return `<div class="endCard"><span class="endCheck">${icon('check',26)}</span><span class="overline">${next?'EPISODE COMPLETE':allComplete?'YOU’RE CAUGHT UP':'LATEST EPISODE'}</span><h2>${next?esc(next.label):'That’s the latest chapter.'}</h2><p>${next?!next.ready?'The next video is not attached yet.':locked?`Watch early for ${coinLabel(next.price)}, or free on ${freeDate(next.freeAt)}.`:'Your next chapter is ready.':'Come back to your series for future releases.'}</p>${nextAction(s,e)}<button class="textButton" data-action="replay-episode">Replay ${esc(e.label)}</button>${!next?'<a class="textButton" href="#explore">Explore more stories</a>':''}</div>`;}
function player(id,part){const s=getSeries(id),e=episodeBy(id,part);if(!s||!e)return notFound();const locked=episodeAccess(e,state)==='locked',unavailable=!e.ready;return `<section class="watchPage"><div class="watchHeader"><a class="iconButton" href="#series/${id}" aria-label="Back to ${esc(s.title)}">${icon('back')}</a><div><h1>${esc(s.title)}</h1><p>${esc(e.label)}${s.localPreview?' · Local preview':''}</p></div>${s.localPreview?'<a class="secondary" href="#studio">Studio</a>':`<button class="iconButton" data-action="save" data-id="${id}" aria-label="${state.saved.includes(id)?'Remove from list':'Save'} ${esc(s.title)}" aria-pressed="${state.saved.includes(id)}">${icon(state.saved.includes(id)?'check':'plus')}</button>`}</div><div class="watchGrid"><div class="watchMain"><div class="watchStage">${locked?`<div class="lockedScreen">${imageTag(e.still)}<div><span class="overline">EARLY ACCESS</span><h2>${esc(e.label)}</h2><p>${esc(s.title)} · ${runtime(e.duration)}</p><button class="primary" data-action="unlock" data-id="${id}" data-part="${part}">Watch early · ${coinLabel(e.price)}</button><a class="waitNote" href="#series/${id}">Or wait. Free on ${freeDate(e.freeAt)}.</a></div></div>`:unavailable?`<div class="playerMessage"><h2>Video not attached</h2><p>Return to the studio to add this episode’s video.</p><a class="primary" href="#studio">Open studio</a></div>`:`<video id="episodeVideo" data-episode="${e.id}" controls playsinline preload="metadata" poster="${esc(e.still)}"></video><div id="playerFeedback" class="playerFeedback" role="status"><span>Loading episode…</span></div><div id="episodeEnd" class="episodeEnd" hidden>${endCard(s,e)}</div>`}</div><div class="watchControls"><button class="secondary episodeDrawerButton" data-action="episode-drawer" data-id="${id}" data-part="${part}">${icon('library')} Episodes</button><span class="currentInstallment">${esc(e.label)}</span><div id="nextAction">${nextAction(s,e)}</div></div></div><aside class="episodeRail"><div class="railHeading"><h2>Episodes</h2><p>${esc(s.title)}</p></div><div id="watchEpisodeList">${episodesFor(s).map(item=>episodeRow(s,item,item.id===e.id)).join('')}</div></aside></div></section>`;}
function showPlayerFeedback(kind){const node=$('#playerFeedback');if(!node)return;node.hidden=false;node.dataset.kind=kind;node.setAttribute('role',kind==='error'?'alert':'status');node.innerHTML=kind==='error'?`<h2>This episode couldn’t load.</h2><p>Your place is saved. Try again when your connection is ready.</p><button class="primary" data-action="retry-video">Retry episode</button>`:kind==='blocked'?'<button class="primary" data-action="play-video">Tap to play</button>':'<span>Loading episode…</span>';}
async function attemptPlay(){const v=$('#episodeVideo');if(!v)return;if(playbackHeld){showPlayerFeedback('blocked');return;}try{await v.play();if(v!==$('#episodeVideo'))return;if($('#playerFeedback'))$('#playerFeedback').hidden=true;}catch(error){if(v!==$('#episodeVideo'))return;showPlayerFeedback(error.name==='NotAllowedError'?'blocked':'error');}}
async function bindPlayer(id,part){const s=getSeries(id),e=episodeBy(id,part),v=$('#episodeVideo');if(!v)return;let lastSaved=0,replaying=state.completed.includes(e.id);if(!s.localPreview){state.history=[...state.history.filter(k=>k!==e.id),e.id];persist();}v.onloadedmetadata=()=>{if(v!==$('#episodeVideo'))return;document.querySelector('.watchGrid').dataset.aspect=v.videoWidth>=v.videoHeight?'wide':'portrait';const saved=state.completed.includes(e.id)?0:state.progress[e.id]||0;v.currentTime=Math.min(saved,Math.max(0,v.duration-.1));attemptPlay();};v.onloadeddata=()=>{if(v!==$('#episodeVideo'))return;if($('#playerFeedback')?.dataset.kind==='loading')$('#playerFeedback').hidden=true;};v.onplaying=()=>{if(v!==$('#episodeVideo'))return;if(replaying&&!s.localPreview){state.completed=state.completed.filter(k=>k!==e.id);replaying=false;persist();}if($('#playerFeedback'))$('#playerFeedback').hidden=true;};v.onwaiting=()=>{if(v!==$('#episodeVideo'))return;if(!v.ended)showPlayerFeedback('loading');};v.ontimeupdate=()=>{if(v!==$('#episodeVideo'))return;if(s.localPreview)return;state.progress[e.id]=v.currentTime;if(Date.now()-lastSaved>5000){persist();lastSaved=Date.now();}};v.onpause=()=>persist();v.onended=()=>{if(v!==$('#episodeVideo'))return;if(!s.localPreview){state=markEpisodeCompleted(state,{...e,duration:v.duration});persist();}$('#episodeEnd').innerHTML=endCard(s,e);$('#episodeEnd').hidden=false;$('#watchEpisodeList').innerHTML=episodesFor(s).map(item=>episodeRow(s,item,item.id===e.id)).join('');};v.onerror=()=>{if(v===$('#episodeVideo'))showPlayerFeedback('error');};try{if(e.mediaKey){const file=await readFile(e.mediaKey);if(v!==$('#episodeVideo'))return;if(!file)throw Error('Missing video');const url=URL.createObjectURL(file);pageUrls.push(url);v.src=url;}else v.src=e.src;v.load();}catch{if(v===$('#episodeVideo'))showPlayerFeedback('error');}}
function openEpisodeDrawer(id,part){const s=getSeries(id);openModal(`<div class="episodeDrawer"><h2>Episodes</h2><p>${esc(s.title)}</p>${episodesFor(s).map(e=>episodeRow(s,e,e.part===part)).join('')}</div>`,'episodeSheet');requestAnimationFrame(()=>$('#modal [aria-current="true"]')?.scrollIntoView({block:'nearest'}));}

function library(){const active=SERIES.filter(s=>s.parts&&state.history.some(k=>k.startsWith(s.id+':')));const saved=SERIES.filter(s=>state.saved.includes(s.id));const upcoming=SERIES.filter(s=>state.reminders.includes(s.id));return `${heading('Your library','Your stories, right where you left them.')}<div class="tabBar">${['Continue','Saved','Upcoming'].map(t=>`<button class="${t===libraryTab?'active':''}" data-action="library-tab" data-tab="${t}" aria-pressed="${t===libraryTab}">${t}</button>`).join('')}</div>${libraryTab==='Continue'?active.length?`<div class="continueGrid">${active.map(s=>continueCard(s)).join('')}</div>`:'<div class="empty"><h2>Your next story starts here.</h2><p>Start an episode and we’ll keep your place.</p><a class="primary" href="#home">Find a story</a></div>':libraryTab==='Saved'?saved.length?`<div class="browseGrid">${saved.map(card).join('')}</div>`:'<div class="empty"><h2>No saved stories yet.</h2><a class="primary" href="#explore">Explore stories</a></div>':`<p class="muted">Release reminders saved on this device. No notifications are sent in this demo.</p>${upcoming.length?`<div class="browseGrid">${upcoming.map(card).join('')}</div>`:'<div class="empty"><h2>Something to look forward to.</h2><p>Save a release reminder from any series page.</p></div>'}`}`;}
function transactionError(message){const node=$('#transactionError');if(node){node.hidden=false;node.textContent=message;}$('#modal').querySelectorAll('button').forEach(b=>b.disabled=false);}
function checkout(id,part){const s=getSeries(id),e=episodeBy(id,part);if(!e)return;if(episodeAccess(e,state)!=='locked'){go(`watch/${id}/${part}`);return;}const q=quoteEpisodeUnlock(state,e);openModal(`<div class="checkoutContent"><span class="overline">EARLY ACCESS</span><h2>Watch ${esc(e.label)} now.</h2><div class="checkoutStory">${imageTag(e.still)}<div><h3>${esc(s.title)}</h3><p>${esc(e.label)} · ${runtime(e.duration)}</p><span>Free release: ${freeDate(e.freeAt)}</span></div></div><div class="priceRows"><div><span>Episode price</span><b>${coinLabel(q.spent)}</b></div><div><span>From your balance</span><b>${coinLabel(q.balanceUsed)}</b></div>${q.added?`<div><span>Add exactly what you need</span><b>${coinLabel(q.added)} · ${money(q.added)}</b></div><div><span>Platform fee (10%)</span><b>${money(q.fee)}</b></div>`:''}<div class="priceTotal"><strong>${q.added?'Total today':'Balance after unlock'}</strong><strong>${q.added?money(q.cash):coinLabel(q.balanceAfter)}</strong></div></div>${q.added?`<div class="paymentMethod">${icon('card')}<div><strong>Demo payment</strong><span>No card details needed. No real charge.</span></div></div>`:'<p class="muted">No extra fee when spending coins you already have.</p>'}<p id="transactionError" class="inlineError" role="alert" hidden></p><button class="primary full" data-action="pay-unlock" data-id="${id}" data-part="${part}">${q.added?'Demo pay '+money(q.cash)+' & unlock':'Unlock with '+coinLabel(q.spent)} ${icon('arrow',18)}</button><button class="waitButton" data-action="wait-release" data-id="${id}">I’ll wait. Back to episodes.</button><p class="fineprint">A one-time simulated unlock. No subscription or automatic purchases.</p></div>`,'checkoutSheet');}
function finishUnlock(id,part){const s=getSeries(id),e=episodeBy(id,part);if(!e)return;let result;try{result=purchaseEpisode(state,e,{id:crypto.randomUUID(),title:s.title+' · '+e.label,date:new Date().toLocaleDateString('en-US',{month:'short',day:'numeric'}),series:id,part});}catch(error){transactionError(error.message);return;}if(result.duplicate){closeModal();go(`watch/${id}/${part}`);return;}if(!commitState(result.next)){transactionError('The demo purchase could not be saved. Your balance and access are unchanged. Check browser storage and try again.');return;}const receipt=state.receipts.at(-1);playbackHeld=true;render();const v=$('#episodeVideo');if(v)v.pause();openModal(`<div class="successContent"><span class="successIcon">${icon('check',30)}</span><h2>${esc(e.label)} is unlocked.</h2><p>${esc(s.title)}</p><button class="primary full" data-action="watch-purchased" data-id="${id}" data-part="${part}">Watch now ${icon('play',18)}</button><button class="textButton" data-action="receipt" data-id="${receipt.id}">View receipt</button><p class="fineprint">${receipt.cash?money(receipt.cash)+' demo payment':coinLabel(receipt.spent)+' used from your balance'}. No real charge.</p></div>`,'checkoutSheet');}
function fundCoins(amount){const next=structuredClone(state),fee=Math.round(amount*10)/100;next.balance+=amount;next.receipts.push({id:crypto.randomUUID(),kind:'topup',title:coinLabel(amount)+' added',coins:amount,added:amount,spent:0,balanceUsed:0,balanceAfter:next.balance,cash:amount+fee,fee,date:new Date().toLocaleDateString('en-US',{month:'short',day:'numeric'})});if(!commitState(next)){transactionError('These demo coins could not be saved. Nothing was added. Free browser storage and try again.');return;}closeModal();render();toast(coinLabel(amount)+' added. Demo payment complete.');}
function receipt(id){const r=state.receipts.find(r=>r.id===id);if(!r)return;openModal(`<div class="checkoutContent"><span class="overline">DEMO RECEIPT</span><h2>${esc(r.title)}</h2><p>${esc(r.date)}</p><div class="priceRows">${r.kind==='unlock'?`<div><span>Coins spent on episode</span><b>${coinLabel(r.spent??r.coins)}</b></div><div><span>From existing balance</span><b>${r.balanceUsed===undefined?'Not recorded':coinLabel(r.balanceUsed)}</b></div>`:''}<div><span>Coins added</span><b>${r.added===undefined?(r.kind==='topup'?coinLabel(r.coins):'Not recorded'):coinLabel(r.added)}</b></div><div><span>Platform fee paid today</span><b>${money(r.fee)}</b></div><div><span>Balance after transaction</span><b>${r.balanceAfter===undefined?'Not recorded':coinLabel(r.balanceAfter)}</b></div><div class="priceTotal"><strong>Demo payment</strong><strong>${money(r.cash)}</strong></div></div><p class="fineprint">This is a simulated transaction, not a payment receipt.</p></div>`,'checkoutSheet');}
function readiness(e){return !e.mediaKey?'Needs video':e.status==='Scheduled'?'Scheduled':'Draft';}
function studio(){return `${heading('Creator studio','Your stories, taking shape.')}<div class="studioToolbar"><span class="sampleBadge">Local workspace</span><button class="primary" data-action="new-series">${icon('plus',18)} New series</button></div><div class="studioSeries">${state.drafts.map(d=>`<article class="projectCard"><div class="projectHeader" data-cover-id="${d.id}">${imageTag(d.cover||'assets/draft-cover.svg')}<div><span class="overline">${esc(d.shelf)}${d.sample?' · SAMPLE':''}</span><h2>${esc(d.title)}</h2><p>${esc(d.genre)}</p></div><details class="episodeActions"><summary aria-label="Series actions for ${esc(d.title)}">•••</summary><div><button data-action="edit-series" data-id="${d.id}">Edit series</button><button data-action="delete-series" data-id="${d.id}">Delete draft</button></div></details></div><div class="projectEpisodes">${d.episodes.map((e,i)=>`<div class="projectEpisode"><span>${i+1}</span><div><strong>${esc(e.title)}</strong><small>${e.date?'Free release '+esc(e.date):'Release date not set'}</small></div><span class="status ${readiness(e)==='Scheduled'?'scheduled':''}">${readiness(e)}</span><details class="episodeActions"><summary aria-label="Actions for ${esc(e.title)}">•••</summary><div><button data-action="edit-episode" data-id="${d.id}" data-episode="${e.id}">Edit episode</button><button data-action="move-episode" data-id="${d.id}" data-episode="${e.id}" data-direction="up" ${i===0?'disabled':''}>Move earlier</button><button data-action="move-episode" data-id="${d.id}" data-episode="${e.id}" data-direction="down" ${i===d.episodes.length-1?'disabled':''}>Move later</button><button data-action="delete-episode" data-id="${d.id}" data-episode="${e.id}">Remove episode</button></div></details></div>`).join('')}</div><div class="projectFooter"><button class="textButton" data-action="add-episode" data-id="${d.id}">${icon('plus',16)} Add episode</button><button class="textButton" data-action="preview-draft" data-id="${d.id}">Preview as a viewer ${icon('arrow',16)}</button></div></article>`).join('')||'<div class="empty"><h2>Your next story starts here.</h2><button class="primary" data-action="new-series">Create a series</button></div>'}</div><p class="fineprint">Drafts and uploaded media stay on this device. Nothing is published.</p>`;}
function episodeEditor(id,epid){const d=state.drafts.find(x=>x.id===id),ep=d?.episodes.find(e=>e.id===epid)||{title:'',date:'',status:'Draft',price:1};if(!d)return;openModal(`<form class="editorForm" id="episodeForm" data-id="${id}" data-episode="${epid||''}"><span class="overline">${esc(d.title)}</span><h2>${epid?'Edit episode':'Add an episode'}</h2><label>Episode title<input name="title" required value="${esc(ep.title)}" placeholder="The next chapter"></label><label class="fileDrop">${icon('play',26)} Episode video<input name="video" type="file" accept="video/mp4,video/webm"><small>${ep.mediaKey?'A video is attached. Select a file to replace it.':'Attach a video before scheduling.'}</small></label><div class="formRow"><label>Free-release date<input name="date" type="date" value="${esc(ep.date)}"></label><label>Status<select name="status"><option ${ep.status==='Draft'?'selected':''}>Draft</option><option ${ep.status==='Scheduled'?'selected':''}>Scheduled</option></select></label></div><label class="checkboxLabel"><input type="checkbox" name="early" ${ep.early?'checked':''}> Offer paid early access</label><div id="earlyFields" ${ep.early?'':'hidden'}><label>Early-access start date<input name="earlyDate" type="date" value="${esc(ep.earlyDate||'')}" ${ep.early?'':'disabled'}></label><label>Early-access price (coins)<input name="price" type="number" min="1" step="1" value="${ep.price||1}" ${ep.early?'':'disabled'}><small>1 coin = US$1. Platform fee is separate.</small></label></div><p id="formError" class="inlineError" role="alert" hidden></p><button class="primary full" type="submit">Save episode ${icon('check',18)}</button><p class="fineprint">These are local preview settings. No public release is scheduled.</p></form>`,'editorSheet');const form=$('#episodeForm');form.elements.early.onchange=()=>{const enabled=form.elements.early.checked;$('#earlyFields').hidden=!enabled;form.elements.earlyDate.disabled=form.elements.price.disabled=!enabled;};form.onsubmit=saveEpisode;}
async function inspectVideo(file){return new Promise((resolve,reject)=>{const v=document.createElement('video'),url=URL.createObjectURL(file),timer=setTimeout(()=>done(Error('Video metadata could not be read. Try an MP4 or WebM export.')),10000);function done(error){clearTimeout(timer);const duration=Number.isFinite(v.duration)?Math.round(v.duration):0;v.removeAttribute('src');v.load();URL.revokeObjectURL(url);error?reject(error):resolve(duration);}v.preload='metadata';v.onloadedmetadata=()=>done();v.onerror=()=>done(Error('This video could not be opened. Choose a supported MP4 or WebM.'));v.src=url;});}
async function deleteFile(id){if(!id)return;const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('files','readwrite');t.objectStore('files').delete(id);t.oncomplete=resolve;t.onerror=()=>reject(t.error);});}
async function saveEpisode(event){event.preventDefault();const form=event.target,submit=form.querySelector('[type=submit]'),f=new FormData(form);submit.disabled=true;let newKey;try{const d=state.drafts.find(x=>x.id===form.dataset.id),id=form.dataset.episode||crypto.randomUUID(),old=d.episodes.find(e=>e.id===id),file=f.get('video');const ep={id,title:String(f.get('title')).trim(),date:f.get('date'),status:f.get('status'),price:f.get('early')?Number(f.get('price')):0,early:!!f.get('early'),earlyDate:f.get('early')?f.get('earlyDate'):'',mediaKey:old?.mediaKey,duration:old?.duration||0};const day=new Date(),today=[day.getFullYear(),String(day.getMonth()+1).padStart(2,'0'),String(day.getDate()).padStart(2,'0')].join('-');const validation=validateEpisodeSchedule(ep,!!(file.size||old?.mediaKey),today);if(validation)throw Error(validation);if(file.size){if(!['video/mp4','video/webm'].includes(file.type))throw Error('Choose an MP4 or WebM video.');ep.duration=await inspectVideo(file);newKey=d.id+':'+id+':'+crypto.randomUUID();await putFile(newKey,file);ep.mediaKey=newKey;}const next=structuredClone(state),target=next.drafts.find(x=>x.id===d.id);if(old)target.episodes=target.episodes.map(e=>e.id===id?ep:e);else target.episodes.push(ep);if(!commitState(next))throw Error('The episode could not be saved. Free browser storage and try again.');if(newKey&&old?.mediaKey)deleteFile(old.mediaKey).catch(()=>{});closeModal();render();toast('Episode saved on this device.');}catch(error){if(newKey)deleteFile(newKey).catch(()=>{});$('#formError').hidden=false;$('#formError').textContent=error.message;submit.disabled=false;}}
function previewDraft(id){origins['draft-'+id]={route:'studio',scroll:scrollY,query,category,libraryTab};go('series/draft-'+id);}
function confirmDraftRemoval(id,episodeId){const d=state.drafts.find(x=>x.id===id),e=d?.episodes.find(x=>x.id===episodeId);if(!d)return;openModal(`<div class="checkoutContent"><h2>${episodeId?'Remove this episode?':'Delete this draft?'}</h2><p>${esc(e?.title||d.title)}</p><p class="muted">This removes the local draft and its attached preview files. Your original files on disk are untouched.</p><button class="primary full" data-action="confirm-removal" data-id="${id}" ${episodeId?`data-episode="${episodeId}"`:''}>${episodeId?'Remove episode':'Delete draft'}</button><button class="waitButton" data-action="close">Keep it</button><p id="transactionError" class="inlineError" role="alert" hidden></p></div>`);}
async function removeDraftItem(id,episodeId){const d=state.drafts.find(x=>x.id===id);if(!d)return;const removed=episodeId?d.episodes.filter(e=>e.id===episodeId):d.episodes;const next=structuredClone(state);if(episodeId)next.drafts.find(x=>x.id===id).episodes=next.drafts.find(x=>x.id===id).episodes.filter(e=>e.id!==episodeId);else next.drafts=next.drafts.filter(x=>x.id!==id);if(!commitState(next)){transactionError('The change could not be saved. Your draft is unchanged.');return;}for(const e of removed)deleteFile(e.mediaKey).catch(()=>{});if(!episodeId)deleteFile(d.coverKey).catch(()=>{});closeModal();render();toast(episodeId?'Episode removed.':'Draft deleted.');}
function moveEpisode(id,episodeId,direction){const next=structuredClone(state),d=next.drafts.find(x=>x.id===id),i=d.episodes.findIndex(e=>e.id===episodeId),j=i+(direction==='up'?-1:1);if(i<0||j<0||j>=d.episodes.length)return;[d.episodes[i],d.episodes[j]]=[d.episodes[j],d.episodes[i]];if(!commitState(next)){toast('The new order could not be saved.');return;}render();}
async function hydratePageMedia(version){for(const img of document.querySelectorAll('img[data-media-key]')){try{const file=await readFile(img.dataset.mediaKey);if(version!==pageVersion)return;if(!file)continue;const url=URL.createObjectURL(file);pageUrls.push(url);img.src=url;}catch{}}}

async function saveSeries(event){event.preventDefault();const form=event.target,submit=form.querySelector('[type=submit]'),f=new FormData(form);submit.disabled=true;let newKey;try{const id=form.dataset.id||crypto.randomUUID(),old=state.drafts.find(d=>d.id===id),cover=f.get('cover');let coverKey=old?.coverKey;if(cover.size){if(!/^image\/(png|jpeg|webp)$/.test(cover.type))throw Error('Choose a PNG, JPEG, or WebP cover.');newKey=id+':cover:'+crypto.randomUUID();await putFile(newKey,cover);coverKey=newKey;}const result={...old,id,title:String(f.get('title')).trim(),genre:String(f.get('genre')).trim(),shelf:f.get('shelf'),description:String(f.get('description')).trim(),tags:f.get('tags'),coverKey,episodes:old?.episodes||[]};if(!result.title||!result.genre||!result.description)throw Error('Complete the series title, genre, and description.');const next=structuredClone(state);if(old)next.drafts=next.drafts.map(d=>d.id===id?result:d);else next.drafts.push(result);if(!commitState(next))throw Error('The series could not be saved. Check browser storage and try again.');if(newKey&&old?.coverKey)deleteFile(old.coverKey).catch(()=>{});closeModal();render();toast('Series saved on this device.');}catch(error){if(newKey)deleteFile(newKey).catch(()=>{});$('#seriesError').hidden=false;$('#seriesError').textContent=error.message;submit.disabled=false;}}

async function action(event){const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,part=el.dataset.part;
 if(a==='appearance')return showAppearance();
 if(a==='set-appearance'){const saved=window.ddAppearance.set(el.dataset.appearance);if(!saved)toast('Theme changed for this visit. Your browser could not save the preference.');return;}
 if(a==='close'){closeModal();return;}
 if(a==='filter'){category=el.dataset.category;if(route==='home'){$('#homeResults').innerHTML=homeContent();document.querySelectorAll('.chip').forEach(b=>{b.classList.toggle('selected',b.dataset.category===category);b.setAttribute('aria-pressed',b.dataset.category===category);});observeFeature();}else render();return;}
 if(a==='category'){category=el.dataset.category;go('explore');return;}
 if(a==='clear-search'){query='';category='Explore';render();return;}
 if(a==='feature'){$('.featureTrack').scrollTo({left:Number(el.dataset.index)*$('.featureTrack').clientWidth,behavior:event.detail===0||matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});return;}
 if(a==='library-tab'){libraryTab=el.dataset.tab;render();return;}
 if(a==='save'){state.saved=state.saved.includes(id)?state.saved.filter(s=>s!==id):[...state.saved,id];persist();if(route.startsWith('watch/')){el.innerHTML=icon(state.saved.includes(id)?'check':'plus');el.setAttribute('aria-pressed',state.saved.includes(id));el.setAttribute('aria-label',(state.saved.includes(id)?'Remove from list ':'Save ')+getSeries(id).title);toast(state.saved.includes(id)?'Saved to your library':'Removed from your library');}else render();return;}
 if(a==='remind'){if($('#modal').open)closeModal();state.reminders=state.reminders.includes(id)?state.reminders.filter(s=>s!==id):[...state.reminders,id];persist();render();toast(state.reminders.includes(id)?'Added to your reminder list. Demo only; no notification sent.':'Removed from your reminder list.');return;}
 if(a==='unlock')return checkout(id,part);
 if(a==='pay-unlock'){el.disabled=true;finishUnlock(id,part);return;}
 if(a==='watch-purchased'){playbackHeld=false;closeModal();go(`watch/${id}/${part}`);return;}
 if(a==='topup')return topup();
 if(a==='choose-coins'){topup(Number(el.dataset.amount));document.querySelector('.coinOptions .selected')?.focus({preventScroll:true});return;}
 if(a==='buy-coins'){el.disabled=true;fundCoins(Number(el.dataset.amount));return;}
 if(a==='reset-viewing'){openModal('<div class="checkoutContent"><h2>Reset viewing progress?</h2><p>This clears demo watch history and completion markers. Saved stories, purchases and creator drafts stay.</p><button class="primary full" data-action="confirm-viewing-reset">Reset viewing progress</button><button class="waitButton" data-action="close">Keep progress</button></div>');return;}if(a==='confirm-viewing-reset'){const next=structuredClone(state);next.history=[];next.progress={};next.completed=[];if(!commitState(next)){toast('Progress could not be reset.');return;}closeModal();render();toast('Viewing progress reset.');return;}
 if(a==='reset-purchases'){openModal('<div class="checkoutContent"><h2>Try checkout from the start?</h2><p>This clears only demo coins, unlocks, and receipts. Your library and creator drafts stay saved.</p><button class="primary full" data-action="confirm-reset">Reset demo purchases</button></div>');return;}if(a==='confirm-reset'){const next=structuredClone(state);next.balance=0;next.unlocked=[];next.receipts=[];next.demoRelease='before';if(!commitState(next)){toast('The demo reset could not be saved.');return;}closeModal();render();toast('Demo purchases reset.');return;}if(a==='receipt')return receipt(id);
 if(a==='how-it-works')return howItWorks();
 if(a==='start-over'){const first=episodesFor(getSeries(id))[0];if(!first)return;const next=structuredClone(state);next.progress[first.id]=0;next.completed=next.completed.filter(k=>k!==first.id);if(!commitState(next)){toast('Your playback position could not be saved.');return;}go(`watch/${id}/${first.part}`);return;}
 if(a==='return-origin'){if(id?.startsWith('draft-'))go('studio');else returnOrigin(id);return;}
 if(a==='episode-drawer')return openEpisodeDrawer(id,part);
 if(a==='wait-release'){closeModal();go('series/'+id);return;}
 if(a==='retry-video'){const v=$('#episodeVideo');if(v){showPlayerFeedback('loading');v.load();}return;}
 if(a==='play-video')return attemptPlay();
 if(a==='replay-episode'){const v=$('#episodeVideo');if(v){$('#episodeEnd').hidden=true;v.currentTime=0;attemptPlay();}return;}
 if(a==='move-episode')return moveEpisode(id,el.dataset.episode,el.dataset.direction);
 if(a==='delete-series')return confirmDraftRemoval(id);
 if(a==='delete-episode')return confirmDraftRemoval(id,el.dataset.episode);
 if(a==='confirm-removal')return removeDraftItem(id,el.dataset.episode);
 if(a==='new-series')return seriesEditor();
 if(a==='edit-series')return seriesEditor(id);
 if(a==='add-episode')return episodeEditor(id);
 if(a==='edit-episode')return episodeEditor(id,el.dataset.episode);
 if(a==='preview-draft')return previewDraft(id);
}
document.addEventListener('click',e=>{const link=e.target.closest('a');const href=link?.getAttribute('href');if(link?.closest('#modal')&&href?.startsWith('#watch/')){closeModal();if(href.slice(1)===route){e.preventDefault();return;}}if(href?.startsWith('#series/')){rememberOrigin(href.slice(8));try{sessionStorage.setItem('dd-origins',JSON.stringify(origins));}catch{}}if(link?.getAttribute('href')==='#explore')category='Explore';if(link?.getAttribute('href')==='#home')category='Originals';if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return;}action(e);});
window.addEventListener('pagehide',persist);
render();
